L23_1 = "\232\167\129\229\136\176\229\165\185\231\154\132\230\150\185\230\179\149\229\190\136\231\174\128\229\141\149\227\128\130\229\143\170\232\166\129\228\187\142\231\142\176\229\156\168\230\137\147\229\188\128\231\154\132\232\191\153\230\137\135\233\151\168\232\191\155\229\142\187\229\176\177\232\161\140\228\186\134\227\128\130"
